evidence_gate.initial_before_update:
{
  "choice": "Cedar",
  "status": "잠정",
  "budget_cap": 1200,
  "decision_scope": "연간 예산 상한과 키보드 접근성 필수 조건을 만족하는 공급업체 추천",
  "criteria": {
    "hard_constraint": "키보드 접근성",
    "primary_preference": "월 지원업무 절감 시간 최대화",
    "tie_breakers": [
      "예산 여유",
      "지원 응답 시간"
    ]
  },
  "evidence": [
    {
      "provider": "Cedar",
      "listed_cost": 900,
      "monthly_support_hours_saved": 6,
      "support_response_days": 2,
      "keyboard_accessibility": "독립 접근성 감사 통과",
      "evidence_state": "사용자 제공 초기 검증 기록"
    },
    {
      "provider": "Larch",
      "listed_cost": 1100,
      "monthly_support_hours_saved": 4,
      "support_response_days": 2,
      "keyboard_accessibility": "독립 접근성 감사 통과",
      "evidence_state": "사용자 제공 초기 검증 기록"
    }
  ],
  "grounds": [
    "두 후보의 기재 비용은 1200 상한 이하이다.",
    "키보드 접근성이 필수 조건이며, 두 후보 모두 독립 접근성 감사 통과 기록이 있다.",
    "지원 응답 시간은 둘 다 2일로 같고, Cedar가 월 절감 시간은 6시간으로 Larch의 4시간보다 많으며 기재 비용도 낮다."
  ],
  "assumptions": [
    {
      "statement": "900과 1100은 같은 예산 단위로 비교할 수 있는 기재 비용이다.",
      "evidence_state": "가정함",
      "decision_impact": "단위나 비용 기간이 다르면 예산 적합성 비교가 달라질 수 있다."
    },
    {
      "statement": "기재된 월 지원업무 절감 시간은 같은 범위와 측정 기준으로 비교할 수 있다.",
      "evidence_state": "가정함",
      "decision_impact": "측정 범위가 다르면 절감 시간 우선의 추천이 약해질 수 있다."
    },
    {
      "statement": "초기 기록에 없는 반복 지원비가 예산 적합성을 바꾸지 않는다고는 아직 확인할 수 없다.",
      "evidence_state": "미검증",
      "decision_impact": "반복 지원비가 있으면 실제 연간 총비용과 예산 여유가 달라질 수 있다."
    }
  ],
  "uncertainty": [
    "감사 통과 기록과 성과 수치는 사용자 제공 초기 기록에 근거하며, 이 문서만으로 더 넓은 사용 맥락까지 검증된 것으로 일반화하지 않는다.",
    "반복 지원비의 존재·범위·적용 조건은 미확인이다. 따라서 이 선택은 기재 비용과 초기 기록만을 이용한 잠정 추천이다."
  ],
  "authority": "추천 기록만 작성한다. 구매·배포·연락을 승인하거나 수행할 권한은 없다."
}

